        "phonetic": "Chuuou no seki wa umatte orimasu ga, ushiro no seki nara mada aki ga gozaimasu.",
        "translation": "Ghế ở giữa đã kín chỗ rồi ạ, nhưng hàng ghế sau thì vẫn còn chỗ trống.",
        "grammarNote": "埋まっております: Đã bị chiếm hết chỗ (kính ngữ)."
