      {
        "id": "ja-n5-12-s3",
        "text": "じゃあ、後ろの真ん中の席でお願いします。ポップコーンも買えますか？",
        "furigana": "じゃあ、後[うし]ろの真[ま]ん中[なか]の席[せき]でお願[ねが]いします。ポップコーンも買[か]えますか？",
        "phonetic": "Jaa, ushiro no mannaka no seki de onegai shimasu. Poppukoon mo kaemasu ka?",
        "translation": "Vậy lấy cho tôi hàng ghế sau ở chính giữa nhé. Có mua luôn bắp rang bơ ở đây được không?",
        "grammarNote": "真ん中 (mannaka): Ngay chính giữa."
      }
