        "phonetic": "Dono you na osaifu desu ka? Iro ya burando, naka ni haitte ita mono wo oshiete kudasai.",
        "translation": "Ví tiền trông như thế nào ạ? Hãy cho tôi biết màu sắc, nhãn hiệu và đồ vật bên trong ví nhé.",
