        "id": "ja-n4-10-s3",
        "text": "黒い革の長財布で、現金の一万円と在留カードが入っています。",
        "furigana": "黒[くろ]い革[かわ]の長[なが]財[さい]布[ふ]で、現[げん]金[きん]の一[いち]万[まん]円[えん]と在[ざい]留[りゅう]カードが入[はい]っています。",
        "phonetic": "Kuroi kawa no nagazaifu de, genkin no ichiman-en to zairyuu kaado ga haitte imasu.",
        "translation": "Đó là chiếc ví dài bằng da màu đen, bên trong có 10.000 yên tiền mặt và thẻ cư trú.",
