        "translation": "Vâng, đây là máy giặt sấy đời mới nhất nên nước giặt và nước xả vải đều tự động đưa vào ạ.",
        "grammarNote": "洗濯乾燥機: Máy giặt sấy kết hợp; 柔軟剤: Nước xả vải mềm đồ."
