        "phonetic": "Gofuben wo okake shite orimasu. Shuuri sutaffu no tehai ga kanou desu.",
        "translation": "Rất lấy làm tiếc vì sự bất tiện này. Chúng tôi có thể sắp xếp nhân viên kỹ thuật tới sửa chữa ngay.",
        "grammarNote": "手配が可能: Có thể điều phối, sắp xếp nhân sự."
