        "text": "明日の午後二時以降でしたら、自宅におりますのでお願いいたします。",
        "furigana": "明[あ]日[した]の午[ご]後[ご]二[に]時[じ]以[い]降[こう]でしたら、自[じ]宅[たく]におりますのでお願[ねが]いいたします。",
        "phonetic": "Ashita no gogo niji ikou deshitara, jitaku ni orimasu node onegai itashimasu.",
        "translation": "Sau 2 giờ chiều ngày mai thì tôi có ở nhà, nhờ bên mình qua giờ đó giúp tôi nhé.",
