        "translation": "Tôi muốn bắt đầu quản lý tài sản thông qua quỹ NISA mới, người quốc tịch nước ngoài có mở tài khoản được không ạ?",
        "grammarNote": "資産運用 (shisan un'you): Đầu tư sinh lời từ tài sản; NISA: Quỹ đầu tư miễn thuế tại Nhật."
