        "text": "日本国内に居住されており、マイナンバーカードをお持ちであれば問題なくお手続きいただけます。",
        "furigana": "日[に]本[ほん]国[こく]内[ない]に居[きょ]住[じゅう]されており、マイナンバーカードをお持[も]ちであれば問[もん]題[だい]なくお手[て]続[つづ]きいただけます。",
        "phonetic": "Nihon kokunai ni kyoojuu sarete ori, mainambaa kaado wo omochi de areba mondai naku otetsuzuki itadakemasu.",
        "translation": "Nếu quý khách đang cư trú tại Nhật Bản và có thẻ My Number thì hoàn toàn có thể làm thủ tục thuận lợi ạ.",
        "grammarNote": "居住されており: Tôn kính ngữ của 'đang cư trú'; 〜であれば: Thể điều kiện trang trọng."
