        "translation": "Tôi muốn ngắm mặt trời mọc từ đỉnh núi Phú Sĩ, có tour leo núi nào dành cho người mới bắt đầu không ạ?",
        "grammarNote": "ご来光 (goraikou): Cảnh mặt trời mọc linh thiêng từ đỉnh núi cao; 初心者向け: Dành cho người mới."
