        "phonetic": "Genzairyou no choutatsu ni yokisenu chien ga shouji, tousho oyakusoku shite ita nouki ni maniawanai osore ga gozaimasu.",
        "translation": "Do việc thu mua nguyên vật liệu phát sinh sự chậm trễ ngoài dự kiến, có nguy cơ sẽ không kịp thời hạn giao hàng đã cam kết ban đầu.",
        "grammarNote": "予期せぬ (yokisenu): Không ngờ tới, ngoài dự kiến; 〜恐れがある: Có nguy cơ xảy ra điều xấu."
