        "furigana": "品[ひん]質[しつ]管[かん]理[り]には万[ばん]全[ぜん]を期[き]し、これ以[い]上[じょう]の遅[おく]れは絶[ぜっ]対[たい]に発[はっ]生[せい]させないことをお約[やく]束[そく]いたします。",
        "phonetic": "Hinshitsu kanri ni wa banzen wo kishi, kore ijou no okure wa zettai ni hassei sasenai koto wo oyakusoku itashimasu.",
