        "phonetic": "Kono tabi wa otodoke shita seihin ni fuguai ga gozaimashita koto, kasanete fukaku owabi moushiagemasu.",
        "translation": "Về việc sản phẩm giao tới quý khách có lỗi kỹ thuật, một lần nữa chúng tôi xin trân trọng gửi lời tạ lỗi sâu sắc.",
        "grammarNote": "不具合 (fuguai): Sự cố lỗi kỹ thuật; お詫び申し上げます: Lời tạ lỗi chính thức."
