        "furigana": "お客[きゃく]様[さま]からの貴[き]重[ちょう]なご指[し]摘[てき]を真[しん]摯[し]に受[う]け止[と]め、サービス品[ひん]質[しつ]の向[こう]上[じょう]に努[つと]めてまいります。",
