        "furigana": "商[しょう]標[ひょう]権[けん]の侵[しん]害[がい]リスクを未[み]然[ぜん]に防[ふせ]ぐためにも、国[こく]内[ない]外[がい]での権[けん]利[り]化[か]を速[すみ]やかに進[すす]めてまいりましょう。",
