        "furigana": "急[きゅう]激[げき]な円[えん]安[やす]の進[しん]行[こう]は、エネルギーや食[しょく]料[りょう]品[ひん]などの輸[ゆ]入[にゅう]コストを押[お]し上[あ]げ、家[か]計[けい]に大[おお]きな打[だ]撃[げき]を与[あた]えています。",
