        "furigana": "過[か]度[ど]なプレッシャーから従[じゅう]業[ぎょう]員[いん]のメンタルヘルス不[ふ]調[ちょう]を防[ふせ]ぐべく、産[さん]業[ぎょう]医[い]による定[てい]期[き]面[めん]談[だん]を導[どう]入[にゅう]いたしました。",
