        "translation": "Nhằm bảo vệ nhân viên khỏi chứng rối loạn sức khỏe tinh thần do áp lực công việc quá mức, chúng tôi đã đưa vào các buổi tư vấn định kỳ với bác sĩ chuyên trách doanh nghiệp.",
