        "furigana": "一[ひと]人[り]で悩[なや]みを抱[かか]え込[こ]まず、専[せん]門[もん]のカウンセラーにプライバシーを守[まも]られた状[じょう]態[たい]で気[き]軽[がる]に相[そう]談[だん]できる体[たい]制[せい]が重[じゅう]要[よう]です。",
