        "furigana": "脱[だつ]炭[たん]素[そ]社[しゃ]会[かい]の実[じつ]現[げん]に向[む]けて、自[じ]動[どう]車[しゃ]産[さん]業[ぎょう]における電[でん]気[き]自[じ]動[どう]車[しゃ]いわゆるEVへの移[い]行[こう]が世[せ]界[かい]規[き]模[ぼ]で加[か]速[そく]しています。",
        "phonetic": "Datsutanso shakai no jitsugen ni mukete, jidousha sangyou ni okeru denki jidousha iwayuru iibii e no ikou ga sekai kibo de kasoku shite imasu.",
        "translation": "Hướng tới mục tiêu xây dựng một xã hội phi carbon, quá trình chuyển đổi sang xe điện (EV) trong ngành công nghiệp ô tô đang tăng tốc trên quy mô toàn cầu.",
