        "furigana": "利[り]便[べん]性[せい]の追[つい]求[きゅう]の一[いっ]方[ぽう]で、プライバシー侵[しん]害[がい]や著[ちょ]作[さく]権[けん]問[もん]題[だい]、アルゴリズムの偏[へん]見[けん]といった倫[りん]理[り]的[てき]課[か]題[だい]を看[かん]過[か]することはできません。",
        "phonetic": "Ribensei no tsuikyuu no ippou de, puraibashii shingai ya chosakuken mondai, arugorizumu no henken to itta rinriteki kadai wo kanka suru koto wa dekimasen.",
