        "furigana": "生[せい]命[めい]の尊[そん]厳[げん]を冒[ぼう]涜[とく]しかねない技[ぎ]術[じゅつ]の濫[らん]用[よう]を阻[そ]止[し]するため、科[か]学[がく]界[かい]と社[しゃ]会[かい]が一[いっ]致[ち]団[だん]結[けつ]して明[めい]確[かく]な境[きょう]界[かい]線[せん]を設[もう]けるべきです。",
