        "furigana": "医[い]療[りょう]の発[はっ]展[てん]と生[せい]命[めい]倫[りん]理[り]の調[ちょう]和[わ]をいかにして保[たも]つか、人[じん]類[るい]共[きょう]通[つう]の英[えい]知[ち]を結[けっ]集[しゅう]して議[ぎ]論[ろん]を深[ふか]めなければなりません。",
