        "furigana": "賃[ちん]金[ぎん]と物[ぶっ]価[か]の好[こう]循[じゅん]環[かん]を確[かく]認[にん]しつつ、金[きん]利[り]のある世[せ]界[かい]への軟[なん]着[ちゃく]陸[りく]いわゆるソフトランディングを目[め]指[ざ]す舵[かじ]取[と]りが求[もと]められます。",
        "phonetic": "Chingin to bukka no koujunkan wo kakunin shitsutsu, kinri no aru sekai e no nanchakuriku iwayuru sofuto randingu wo mezasu kajitori ga motomeraremasu.",
