        "furigana": "国[こく]債[さい]金[きん]利[り]の急[きゅう]騰[とう]による財[ざい]政[せい]悪[あっ]化[か]のリスクを慎[しん]重[ちょう]に見[み]極[きわ]めながら、持[じ]続[ぞく]的[てき]な経[けい]済[ざい]成[せい]長[ちょう]軌[き]道[どう]を堅[けん]持[じ]しなければなりません。",
        "phonetic": "Kokusai kinri no kyuutou ni yoru zaisei akka no risuku wo shinchou ni mikiwamenagara, jizokuteki na keizai seichou kidou wo kenji shinakereba narimasen.",
