        "furigana": "国[こっ]境[きょう]や業[ぎょう]種[しゅ]の垣[かき]根[ね]を取[と]り払[はら]い、知[ち]恵[え]と情[じょう]熱[ねつ]を分[わ]かち合[あ]うことによってのみ、地[ち]球[きゅう]規[き]模[ぼ]の難[なん]題[だい]に立[た]ち向[む]かうことができます。",
        "phonetic": "Kokkyou ya gyoushu no kakine wo toriharai, chie to jounetsu wo wakachiau koto ni yotte nomi, chikyuu kibo no nandai ni tachimukau koto ga dekimasu.",
        "translation": "Chỉ bằng cách gỡ bỏ rào cản về biên giới quốc gia và lĩnh vực ngành nghề, cùng nhau san sẻ trí tuệ và nhiệt huyết, chúng ta mới có thể đương đầu với các bài toán hóc búa mang tầm vóc toàn cầu.",
