        "text": "本サミットが、共創の精神に基づく新たな時代の幕開けを告げる契機となることを切に願っております。",
        "furigana": "本[ほん]サミットが、共[きょう]創[そう]の精[せい]神[しん]に基[づ]づく新[あら]たな時[じ]代[だい]の幕[まく]開[あ]けを告[つ]げる契[けい]機[き]となることを切[せつ]に願[ねが]っております。",
        "phonetic": "Hon samitto ga, kyousou no seishin ni motozuku arata na jidai no makuake wo tsugeru keiki to naru koto wo setsu ni negatte orimasu.",
        "translation": "Tôi tha thiết cầu chúc cho hội nghị thượng đỉnh lần này sẽ trở thành bước ngoặt báo hiệu hồi chuông mở màn cho một kỷ nguyên mới xây dựng trên tinh thần đồng sáng tạo.",
