        "furigana": "日[ひ]々[び]のささやかな恵[めぐ]みに感[かん]謝[しゃ]し、今[いま]この瞬[しゅん]間[かん]に心[こころ]を研[と]ぎ澄[す]ますマインドフルネスな生[い]き方[かた]が求[もと]められているのです。",
        "phonetic": "Hibi no sasayaka na megumi ni kansha shi, ima kono shunkan ni kokoro wo togisumasu maindofurunesu na ikikata ga motomerarete iru no desu.",
        "translation": "Biết ơn những ân huệ nhỏ bé mỗi ngày và mài giũa tâm trí thanh tịnh trọn vẹn trong khoảnh khắc hiện tại theo lối sống Chánh niệm chính là điều đang được tìm kiếm.",
        "grammarNote": "心を研ぎ澄ます (kokoro wo togisumasu): Mài giũa tâm trí tinh anh; マインドフルネス: Lối sống chánh niệm."
