        "text": "テクノロジーはあくまで人間の幸福と社会の福祉に奉仕するための手段であり、決して自己目的化してはなりません。",
        "furigana": "テクノロジーはあくまで人[にん]間[げん]の幸[こう]福[ふく]と社[しゃ]会[かい]の福[ふく]祉[し]に奉[ほう]仕[し]するための手[しゅ]段[だん]であり、決[けっ]して自[じ]己[こ]目[もく]的[てき]化[か]してはなりません。",
